# AI Office v2.0 Part C Dashboard Certification Release Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found at E:\AI\AI-Office" }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.0-part-c-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @(
 "config\autonomous-enterprise",
 "workspace\autonomous-enterprise\certifications",
 "dashboard\public\data",
 "scripts\autonomous-enterprise",
 "docs"
)) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $BackupPath = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $BackupPath
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\autonomous-enterprise\release-manifest.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\autonomous-enterprise\New-AIOfficeEnterpriseDashboardSnapshot.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\autonomous-enterprise-module.js" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\autonomous-enterprise-module.css" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\autonomous-enterprise\Install-AIOfficeEnterpriseDashboardIntegration.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\autonomous-enterprise\Test-AIOfficeEnterpriseDashboard.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\autonomous-enterprise\Certify-AIOfficeAutonomousEnterprise.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\autonomous-enterprise\Publish-AIOfficeAutonomousEnterpriseRelease.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\autonomous-enterprise\Test-AIOfficeAutonomousEnterprise.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.0-Release-Notes.md" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.0-Part-C-Dashboard-Certification-Release.md" -Base64Content ""
$ScriptPaths = @(
 "E:\AI\AI-Office\scripts\autonomous-enterprise\New-AIOfficeEnterpriseDashboardSnapshot.ps1",
 "E:\AI\AI-Office\scripts\autonomous-enterprise\Install-AIOfficeEnterpriseDashboardIntegration.ps1",
 "E:\AI\AI-Office\scripts\autonomous-enterprise\Test-AIOfficeEnterpriseDashboard.ps1",
 "E:\AI\AI-Office\scripts\autonomous-enterprise\Certify-AIOfficeAutonomousEnterprise.ps1",
 "E:\AI\AI-Office\scripts\autonomous-enterprise\Publish-AIOfficeAutonomousEnterpriseRelease.ps1",
 "E:\AI\AI-Office\scripts\autonomous-enterprise\Test-AIOfficeAutonomousEnterprise.ps1"
)
foreach ($ScriptPath in $ScriptPaths) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $ScriptPath + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; ")) }
}
& "E:\AI\AI-Office\scripts\autonomous-enterprise\New-AIOfficeEnterpriseDashboardSnapshot.ps1" | Out-Null
& "E:\AI\AI-Office\scripts\autonomous-enterprise\Install-AIOfficeEnterpriseDashboardIntegration.ps1"
& "E:\AI\AI-Office\scripts\autonomous-enterprise\Test-AIOfficeEnterpriseDashboard.ps1" | Out-Null
$VersionPath = "E:\AI\AI-Office\config\identity\version.json"
if (Test-Path -LiteralPath $VersionPath -PathType Leaf) {
 $Version = Get-Content -LiteralPath $VersionPath -Raw | ConvertFrom-Json
 $Version.version = "2.0.0"
 $Version.release_name = "Autonomous AI Enterprise"
 $Version.status = "release_candidate"
 $Version.installed_at = (Get-Date).ToString("o")
 $Version.next_planned_milestone = "Self-Hosted AI Office"
 $Version | ConvertTo-Json -Depth 50 | Set-Content -LiteralPath $VersionPath -Encoding UTF8
}
Write-Host ""
Write-Host "AI Office v2.0 Part C Dashboard, Certification, and Release installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan